package sdp
import("strconv";"strings")
type Summary struct{ConnectionAddress string;BundleMIDs []string;ICEUfrag string;Fingerprint string;Media []Media}
type Media struct{Type string;Port int;Protocol string;Formats []string;Codecs []Codec;MID string;Direction string;RTCPMux bool;Connection string}
type Codec struct{PayloadType int;Name string;ClockRate int;Channels int}
func Parse(body string)Summary{var o Summary;var cur *Media;for _,raw:=range strings.Split(strings.ReplaceAll(body,"\r\n","\n"),"\n"){l:=strings.TrimSpace(raw);if len(l)<2||l[1]!='='{continue};v:=l[2:];switch l[:2]{case"m=":p:=strings.Fields(v);if len(p)<3{continue};port,_:=strconv.Atoi(strings.Split(p[1],"/")[0]);o.Media=append(o.Media,Media{Type:p[0],Port:port,Protocol:p[2],Formats:append([]string(nil),p[3:]...)});cur=&o.Media[len(o.Media)-1];case"c=":p:=strings.Fields(v);if len(p)>=3{if cur!=nil{cur.Connection=p[2]}else{o.ConnectionAddress=p[2]}};case"a=":attr(v,&o,cur)}};return o}
func attr(v string,o *Summary,m *Media){if strings.HasPrefix(v,"group:BUNDLE "){o.BundleMIDs=strings.Fields(strings.TrimPrefix(v,"group:BUNDLE "));return};if strings.HasPrefix(v,"ice-ufrag:"){o.ICEUfrag=strings.TrimSpace(strings.TrimPrefix(v,"ice-ufrag:"));return};if strings.HasPrefix(v,"fingerprint:"){o.Fingerprint=strings.TrimSpace(strings.TrimPrefix(v,"fingerprint:"));return};if m==nil{return};switch v{case"sendrecv","sendonly","recvonly","inactive":m.Direction=v;return;case"rtcp-mux":m.RTCPMux=true;return};if strings.HasPrefix(v,"mid:"){m.MID=strings.TrimSpace(strings.TrimPrefix(v,"mid:"));return};if strings.HasPrefix(v,"rtpmap:"){p:=strings.Fields(strings.TrimPrefix(v,"rtpmap:"));if len(p)!=2{return};pt,e:=strconv.Atoi(p[0]);if e!=nil{return};c:=strings.Split(p[1],"/");x:=Codec{PayloadType:pt,Name:c[0]};if len(c)>1{x.ClockRate,_=strconv.Atoi(c[1])};if len(c)>2{x.Channels,_=strconv.Atoi(c[2])};m.Codecs=append(m.Codecs,x)}}
